using System;
using DenTinh.Core;
public static class RpgTests {
    static int passed,failed;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Test(string name,Action f){try{f();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e);}}
    static Simulation Arena(string hero="an"){Simulation g=new Simulation(CatalogData.Create(),hero,71426);g.Props.Clear();g.Enemies.Clear();g.Drops.Clear();g.WorldRelics.Clear();g.Tutorial=5;g.Player.position=new V2(30,20);g.Input=new GameInput{aim=new V2(33,20)};g.Player.crit=0;return g;}
    static void Tick(Simulation g,int n){for(int i=0;i<n;i++)g.Tick(1/60f);}
    static EnemyState Enemy(Simulation g){EnemyState e=g.Spawn("slime",g.Player.position+new V2(1,0),false);e.hp=e.maxHp=10000;e.speed=e.damage=0;return e;}
    static void CompleteTree(Simulation g){foreach(Shrine s in g.Shrines)s.active=true;g.Player.position=Simulation.Altar;Check(g.Interact(),"tree start");EnemyState b=g.Enemies.Find(e=>e.alive&&e.type=="boss");Check(b!=null,"tree boss missing");g.DamageEnemy(b,100000,false);Check(g.Victory,"tree victory");Tick(g,70);g.Player.position=Simulation.Altar;g.Interact();Check(g.Rpg.returnedMemories||g.Interact()&&g.Rpg.returnedMemories,"return memories");}
    public static int Main(){
        Test("Shared RPG content has 32 relics, 20 pedestals, 25 portraits and five quests",delegate{Simulation g=new Simulation(CatalogData.Create(),"an",71426);Check(g.Content.relics.Length==32&&g.WorldRelics.Count==20&&RpgCatalog.Npcs.Length==25&&RpgCatalog.Quests.Length==5,"counts");foreach(StoryNpc n in RpgCatalog.Npcs){Check(n.lines.Length==4,"four dialogue layers");Check(!g.Collides(n.position,.2f),"blocked NPC "+n.id);}foreach(SagaChapter c in RpgCatalog.Chapters)Check(c.position.y>1&&c.position.y<Simulation.Height-1,"chapter outside map "+c.id);});
        Test("XP awards two stat points and one skill point without pending choices",delegate{Simulation g=Arena();EnemyState e=Enemy(g);e.miniBoss=true;e.name="Test";g.DamageEnemy(e,100000,false);Check(g.Player.level==2&&g.Player.statPoints==4&&g.Player.skillPoints==4&&g.PendingLevels==0,"level awards");Check(g.Player.nextXp==Simulation.NextXp(2),"curve");});
        Test("All twelve stats allocate, respec costs 80 and restore cannot inflate derived values",delegate{Simulation g=Arena();g.Player.level=10;g.Player.statPoints=20;foreach(string id in Simulation.StatKeys)Check(g.AllocateStat(id),id);g.Player.gold=500;Check(g.Buy("hp")&&g.Buy("damage"),"training");float hp=g.Player.maxHp,damage=g.Player.damage;for(int i=0;i<10;i++)g=Simulation.Restore(CatalogData.Create(),g.Capture());Check(g.Player.maxHp==hp&&g.Player.damage==damage&&g.Player.statPoints==8,"restore inflation");g.Player.position=Simulation.Home;int gold=g.Player.gold;Check(g.ResetStats()&&g.Player.gold==gold-80&&g.Player.statPoints==20,"reset");});
        Test("Normal attacks use STR, skills use INT and summons use DOM",delegate{Simulation a=Arena(),b=Arena();a.Player.statPoints=50;for(int i=0;i<5;i++)a.AllocateStat("str");a.Player.crit=b.Player.crit=0;EnemyState x=Enemy(a),y=Enemy(b);a.Fire();b.Fire();Tick(a,25);Tick(b,25);Check(x.maxHp-x.hp>y.maxHp-y.hp,"normal coefficient");a=Arena("hoavi");b=Arena("hoavi");a.Player.statPoints=50;for(int i=0;i<5;i++)a.AllocateStat("int");a.Player.crit=b.Player.crit=0;x=Enemy(a);y=Enemy(b);a.Skill("q");b.Skill("q");Tick(a,25);Tick(b,25);Check(x.maxHp-x.hp>y.maxHp-y.hp,"skill coefficient");});
        Test("Boss relic flies, lands, requires F and persists as unclaimed world item",delegate{Simulation g=Arena();EnemyState e=Enemy(g);e.miniBoss=true;e.relic="kimquy";e.name="Huyền Quy";g.DamageEnemy(e,100000,false);Check(!g.Player.Has("kimquy")&&g.WorldRelics.Count==1,"auto pickup");WorldRelic r=g.WorldRelics[0];g.Player.position=r.position;g.Interact();Check(!g.Player.Has("kimquy"),"air pickup");Tick(g,70);g=Simulation.Restore(CatalogData.Create(),g.Capture());r=g.WorldRelics.Find(x=>x.relic=="kimquy");g.Player.position=r.position;Check(g.Interact()&&g.Player.Has("kimquy"),"F pickup");Check(!g.Interact()||g.Player.relics.FindAll(id=>id=="kimquy").Count==1,"duplicate");});
        Test("Guarded and elemental pedestals cannot be looted before unlock",delegate{Simulation g=new Simulation(CatalogData.Create(),"an",71426);WorldRelic r=g.WorldRelics.Find(x=>x.guardCount>0&&!string.IsNullOrEmpty(x.puzzle));g.Player.position=r.position;g.Interact();Check(!r.claimed,"guard bypass");foreach(EnemyState e in g.Enemies.ToArray())if(e.relicGuard==r.relic)g.DamageEnemy(e,100000,false);g.Player.position=r.position+new V2(66/64f,-45/64f);Check(g.Interact()&&r.unlocked,"tool F");g.Player.position=r.position;Check(g.Interact()&&r.claimed,"claim unlocked");});
        Test("VIT regeneration, SPI recovery and living summon DOM ratios stay stable",delegate{Simulation g=Arena("thienvu");g.Player.statPoints=30;g.AllocateStat("vit");g.AllocateStat("spi");g.Player.hp=20;float hp=g.Player.hp;Tick(g,60);Check(g.Player.hp>hp+.7f&&g.Player.hp<hp+.75f,"recovery double scaling");g.TransformElement("earth");g.Skill("r");Tick(g,30);Check(g.Summons.Count==1,"golem");SummonState u=g.Summons[0];hp=u.maxHp;g.AllocateStat("dom");Check(Math.Abs(u.maxHp-hp*1.06f)<.01f,"DOM HP ratio");float expected=u.hp;g=Simulation.Restore(CatalogData.Create(),g.Capture());Check(Math.Abs(g.Summons[0].hp-expected)<.01f,"summon HP restore");});
        Test("Cuoi rescues lethal damage and clears negative statuses",delegate{Simulation g=Arena();g.Player.relics.Add("cuoi");g.Player.hp=1;g.Player.frozen=g.Player.rooted=2;g.Player.shield=20000;g.DamagePlayer(10000);Check(g.Player.hp==1&&g.Player.invulnerable<3,"false lethal trigger with shield");g.Player.invulnerable=0;g.Player.shield=0;g.DamagePlayer(10000);Check(!g.Dead&&g.Player.hp==g.Player.maxHp*.6f&&g.Player.invulnerable==3&&g.Player.frozen==0&&g.Player.rooted==0,"Cuoi rescue");});
        Test("Each hero completes personal quest through actual F, melody, forms and duel",delegate{foreach(HeroQuestDef quest in RpgCatalog.Quests){Simulation g=Arena(quest.hero);int guard=0;while(g.CurrentQuest!=null&&guard++<40){QuestStep s=g.CurrentQuest;int stage=g.Rpg.questStage;if(s.kind=="npc"){StoryNpc n=Array.Find(RpgCatalog.Npcs,x=>x.id==s.target);g.Player.position=n.position;g.Interact();}else if(s.kind=="memory"||s.kind=="memories"){HeroMemory m=Array.Find(RpgCatalog.Memories,x=>x.hero==g.Hero.id&&!g.Rpg.memories.Contains(x.id)&&(x.id==s.target||Array.IndexOf(s.targets,x.id)>=0));Check(m!=null,"memory "+s.target);g.Player.position=m.position;if(m.element!="")g.Player.element=m.element;g.Interact();}else if(s.kind=="notes"){g.Player.position=new V2(3100/64f,80-2185/64f);foreach(int n in new[]{1,3,2,5,4,6,5,8})Check(g.PlayMemoryNote(n),"note");}else if(s.kind=="kill"){EnemyState e=Enemy(g);e.name=s.target;e.miniBoss=true;g.DamageEnemy(e,100000,false);}else if(s.kind=="duel"){g.Player.position=new V2(1830/64f,80-760/64f);g.Interact();EnemyState e=g.Enemies.Find(x=>x.alive&&x.duel);Check(e!=null,"duel spawn");g.DamageEnemy(e,100000,false);}else if(s.kind=="truth")CompleteTree(g);else throw new Exception(s.kind);Check(g.Rpg.questStage>stage||s.kind=="memories",quest.hero+" stuck at "+s.title);}Check(g.Rpg.questComplete,quest.hero+" incomplete");}});
        Test("Six saga chapters require three waves and boss; truth four unlocks only at end",delegate{Simulation g=Arena();CompleteTree(g);Check(g.TruthStage==3,"early truth four");g.Player.position=Simulation.Gate;Check(g.Interact(),"gate");for(int chapter=0;chapter<6;chapter++){SagaChapter c=RpgCatalog.Chapters[chapter];g.Player.position=c.position;for(int stage=0;stage<4;stage++){Check(g.Interact(),"encounter "+chapter+"/"+stage);EnemyState[] enemies=g.Enemies.FindAll(e=>e.alive&&e.saga==chapter).ToArray();Check(enemies.Length>0,"missing encounter");foreach(EnemyState e in enemies)g.DamageEnemy(e,100000,false);g.Tick(.02f);}Check(g.Rpg.chapter==chapter+1,"chapter advance");}Check(g.TruthStage==4,"final truth");});
        Test("Malformed RPG collections recover without exceptions or NaN",delegate{Simulation g=Arena();RunSave d=g.Capture();d.rpg.met=null;d.rpg.memories=null;d.rpg.bosses=null;d.rpg.allies=null;d.rpg.timers=null;d.rpg.trainingHp=99999;d.player.vit=9999;d.player.statPoints=9999;g=Simulation.Restore(CatalogData.Create(),d);Check(g.Player.statPoints==0&&g.Player.vit==2&&!float.IsNaN(g.Player.hp),"bounds");g.Tick(.02f);g.Nearby();});
        Console.WriteLine(passed+"/"+(passed+failed)+" RPG checks passed");return failed==0?0:1;
    }
}
